 internal static class MatureCanvasStoreTests {
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=64*1024*1024,RecursionLimit=48};}
  static Dictionary<string,object> Obj(object value){return (Dictionary<string,object>)value;}
  static Dictionary<string,object> Scene(MatureCanvasDocument document){return Obj(Json().DeserializeObject(document.SceneJson));}
  static Dictionary<string,object> Records(Dictionary<string,object> scene){return Obj(Obj(scene["document"])["store"]);}
  static double N(object value){return Convert.ToDouble(value);}
  static void Reject(Action action,Action<bool,string> check,string message){bool failed=false;try{action();}catch{failed=true;}check(failed,message);}
  static FreeCanvasItem Item(string kind,double x,double y,double endX,double endY){return new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind=kind,X=x,Y=y,EndX=endX,EndY=endY,Stroke=3.5,Color="#4465E9",Width=280,Height=60,FontSize=36,Text="中文 reference\nsecond line"};}
  static void Mutate(MatureCanvasStore store,string id,Action<Dictionary<string,object>> change,Action<bool,string> check,string message){var doc=store.Load(id);var scene=Scene(doc);change(scene);doc.SceneJson=Json().Serialize(scene);string file=Path.Combine(store.Root,id,MatureCanvasStore.ManifestName);byte[] before=File.ReadAllBytes(file);Reject(()=>store.Save(doc),check,message);check(File.ReadAllBytes(file).SequenceEqual(before),message+" preserves committed manifest");}
  // This synthetic fixture is produced and round-tripped by the actual pinned
  // SDK, rather than constructed from the host's permissive property lists.
  internal static void RunSdkSnapshot(string root,string snapshotJson,Action<bool,string> check){
   Directory.CreateDirectory(root);var store=new MatureCanvasStore(Path.Combine(root,"data"));var document=store.Create("actual SDK all tools");var scene=Obj(Json().DeserializeObject(snapshotJson));var records=Records(scene);foreach(var record in records.Values.Select(Obj).Where(r=>r["typeName"].ToString()=="asset")){var props=Obj(record["props"]);string fileId=record["id"].ToString().Substring("asset:".Length);var resource=store.RegisterDataUrl(document,fileId,props["src"].ToString(),props["mimeType"].ToString());props["src"]=MatureCanvasStore.ResourceUrl(document.Id,resource.FileId);}document.SceneJson=store.NormalizeScene(Json().Serialize(scene));store.Save(document);var loaded=store.Load(document.Id);var loadedScene=Scene(loaded);var shapes=Records(loadedScene).Values.Select(Obj).Where(r=>r["typeName"].ToString()=="shape").ToArray();
   check(loaded.SceneJson==document.SceneJson&&loaded.ElementCount==57,"actual SDK snapshot durably preserves all 57 native shapes");
   foreach(string type in new[]{"geo","image","text","line","arrow","draw","group","frame","note","highlight"})check(shapes.Any(s=>s["type"].ToString()==type),"actual SDK save/load retains native "+type+" shapes");
   check(shapes.Where(s=>s["type"].ToString()=="geo").Select(s=>Obj(s["props"])["geo"].ToString()).Distinct().Count()==20,"actual SDK save/load retains all twenty geometric kinds");
   check(shapes.Select(s=>Obj(s["props"])).Where(p=>p.ContainsKey("color")).Select(p=>p["color"].ToString()).Distinct().Count()==13,"actual SDK save/load accepts all thirteen native colors including white");
   check(shapes.Where(s=>s["type"].ToString()=="arrow").Select(s=>Obj(s["props"])["arrowheadEnd"].ToString()).Distinct().Count()==9,"actual SDK save/load retains all nine arrowhead styles");
   check(Records(loadedScene).Values.Select(Obj).Count(r=>r["typeName"].ToString()=="page")==2&&((object[])Obj(loadedScene["session"])["pageStates"]).Length==2,"actual SDK save/load retains two pages and independent viewport states");
   check(Records(loadedScene).Values.Select(Obj).Any(r=>r["typeName"].ToString()=="binding")&&shapes.Any(s=>s["parentId"].ToString().StartsWith("shape:",StringComparison.Ordinal)),"actual SDK save/load retains arrow binding and nested hierarchy");
   check(loaded.Resources.Count==1&&store.ReadFile(loaded,loaded.Resources[0].FileId).Length>0&&!loaded.SceneJson.Contains("data:"),"actual SDK inline image is independently durable and locally resolved");
   var copied=store.CopyProject(loaded,"actual SDK copy");check(copied.ElementCount==57&&copied.SceneJson.Contains(MatureCanvasStore.ResourceUrl(copied.Id,copied.Resources[0].FileId))&&!copied.SceneJson.Contains(MatureCanvasStore.ResourceUrl(loaded.Id,loaded.Resources[0].FileId)),"actual SDK copy retains every shape and rebases only local image source");check(store.Load(copied.Id).SceneJson==copied.SceneJson,"actual SDK copied native snapshot durably reopens without fallback");
  }
